def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to separate build metadata
        parts = v.split('+')
        version_and_pre = parts[0]

        # Split by '-' to separate pre-release
        if '-' in version_and_pre:
            version_part, pre_release = version_and_pre.split('-', 1)
        else:
            version_part = version_and_pre
            pre_release = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, version_part.split('.'))

        # Parse pre-release identifiers
        if pre_release:
            pre_identifiers = pre_release.split('.')
            pre_identifiers = [
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in pre_identifiers
            ]
        else:
            pre_identifiers = None

        return (major, minor, patch, pre_identifiers)

    def compare_key(item):
        index, version = item
        major, minor, patch, pre_identifiers = parse_version(version)

        # For sorting: versions without pre-release come after versions with pre-release
        # So we use (major, minor, patch, has_pre_release, pre_identifiers, index)
        if pre_identifiers is None:
            # No pre-release: sorts after pre-release
            return (major, minor, patch, 1, [], index)
        else:
            # Has pre-release: sorts before non-pre-release
            return (major, minor, patch, 0, pre_identifiers, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [v for _, v in sorted_versions]

